most-frequent-even-element:
class Solution:
    def mostFrequentEven(self, nums: List[int]) -> int:
        from collections import Counter
        evens = [x for x in nums if x % 2 == 0]
        if not evens: return -1
        c = Counter(evens)
        best = min(nums)
        bf = -1
        for k, v in c.items():
            if v > bf or (v == bf and k < best):
                best = k; bf = v
        return best

