class Solution:
    def closetTarget(self, words: List[str], target: str, startIndex: int) -> int:
        n = len(words)
        best = float('inf')
        for i in range(n):
            if words[i] == target:
                d = abs(startIndex-i)
                d = min(d, n-d)
                best = min(best, d)
        return best if best != float('inf') else -1

